# 🟡 中风险：会修改集群/资源状态，执行前请确认目标、影响范围与授权
# 添加容忍度
kubectl patch daemonset node-exporter -p '
{
  "spec": {
    "template": {
      "spec": {
        "tolerations": [
          {
            "key": "node-role.kubernetes.io/control-plane",
            "operator": "Exists",
            "effect": "NoSchedule"
          }
        ]
      }
    }
  }
}'

# 验证
